LessonsView_tmp_stream<<"\n";
	LessonsView_tmp_stream << "<script>\n";
	LessonsView_tmp_stream << "  // ── Toggle unit open/close ──\n";
	LessonsView_tmp_stream << "  function toggleUnit(header) {\n";
	LessonsView_tmp_stream << "    const card = header.closest('.unit-card');\n";
	LessonsView_tmp_stream << "    const badge = card.querySelector('.unit-badge');\n";
	LessonsView_tmp_stream << "    \n";
	LessonsView_tmp_stream << "    // Prevent opening if the unit is explicitly locked\n";
	LessonsView_tmp_stream << "    if (badge && badge.classList.contains('badge-locked')) return;\n";
	LessonsView_tmp_stream << "    \n";
	LessonsView_tmp_stream << "    card.classList.toggle('open');\n";
	LessonsView_tmp_stream << "  }\n";
LessonsView_tmp_stream<<"\n";
	LessonsView_tmp_stream << "  // ── Open lesson modal ──\n";
	LessonsView_tmp_stream << "  let currentLessonRow = null;\n";
LessonsView_tmp_stream<<"\n";
	LessonsView_tmp_stream << "  function openLesson(row, title, unit, desc, duration, accuracy) {\n";
	LessonsView_tmp_stream << "    if (row.classList.contains('locked')) return;\n";
	LessonsView_tmp_stream << "    currentLessonRow = row;\n";
LessonsView_tmp_stream<<"\n";
	LessonsView_tmp_stream << "    // Update modal content\n";
	LessonsView_tmp_stream << "    document.getElementById('modalTitle').textContent = 'Learning the \"' + title + '\" Sign';\n";
	LessonsView_tmp_stream << "    document.getElementById('modalBreadUnit').textContent = unit;\n";
